      role: ['user', Validators.required],
      area: ['General'],
      telefono: ['']
    });
    this.editForm = this.fb.group({
      nombre: ['', [Validators.required, Validators.minLength(3)]],
      alias: ['', [Validators.required, Validators.minLength(3)]],
      role: ['user', Validators.required],
      area: ['General'],
      telefono: [''],
      activo: [true]
    });
