import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { AuthService } from '../services/auth.service';
import { UsersService, ScopePayloadItem } from '../services/users.service';
import { EntidadesService } from '../services/entidades.service';
import { User, USER_AREAS } from '../models/user.model';
import { Entidad, Area } from '../models/entidad.model';

declare const bootstrap: any;

@Component({
  selector: 'app-users',
  templateUrl: './users.component.html',
})
export class UsersComponent implements OnInit {
  users: User[] = [];
  readonly areas = USER_AREAS;
  loading = false;
  error = '';
  successMsg = '';

  // ── Entidades y áreas disponibles ─────────────────────────────────────────
  entidades: Entidad[] = [];

  // ── Estado scope para modal CREAR ─────────────────────────────────────────
  createForm!: FormGroup;
  saving = false;
  cEntidadId: number | null = null;
  cAreaId: number | null = null;
  cEntidadIds: number[] = [];        // para rol soporte (multi)
  cAreasDisponibles: Area[] = [];
  cLoadingAreas = false;

  // ── Estado scope para modal EDITAR ────────────────────────────────────────
  editingUser: User | null = null;
  editForm!: FormGroup;
  savingEdit = false;
  eEntidadId: number | null = null;
  eAreaId: number | null = null;
  eEntidadIds: number[] = [];        // para rol soporte (multi)
  eAreasDisponibles: Area[] = [];
  eLoadingAreas = false;

  constructor(
    private fb: FormBuilder,
    private authService: AuthService,
    private usersService: UsersService,
    private entidadesService: EntidadesService,
    private router: Router
  ) {}

  ngOnInit(): void {
    this.createForm = this.fb.group({
      nombre:   ['', [Validators.required, Validators.minLength(3)]],
      alias:    ['', [Validators.required, Validators.minLength(3)]],
      role:     ['user', Validators.required],
      area:     ['General'],
      telefono: [''],
    });

    this.editForm = this.fb.group({
      nombre:   ['', [Validators.required, Validators.minLength(3)]],
      alias:    ['', [Validators.required, Validators.minLength(3)]],
      role:     ['user', Validators.required],
      area:     ['General'],
      telefono: [''],
      activo:   [true],
    });

    this.loadUsers();
    this.loadEntidades();
  }

  get currentUser(): User | null { return this.authService.currentUser; }

  // ── Carga de datos ─────────────────────────────────────────────────────────

  loadUsers(): void {
    this.loading = true;
    this.usersService.getAll().subscribe({
      next: (data) => { this.users = data; this.loading = false; },
      error: () => { this.error = 'Error al cargar usuarios'; this.loading = false; },
    });
  }

  loadEntidades(): void {
    this.entidadesService.getAllEntidades().subscribe({
      next: (data) => (this.entidades = data),
      error: () => {},
    });
  }

  // ── Helpers de scope ───────────────────────────────────────────────────────

  getScopeLabel(user: User): string {
    if (!user.scope?.length) return user.area ?? '—';
    if (user.role === 'soporte') {
      return user.scope.map(s => s.entidad?.nombre ?? `#${s.entidadId}`).join(', ');
    }
    const s = user.scope[0];
    const entNombre = s.entidad?.nombre ?? `Entidad #${s.entidadId}`;
    const areaNombre = s.area?.nombre ?? (s.areaId ? `Área #${s.areaId}` : null);
    return areaNombre ? `${entNombre} / ${areaNombre}` : entNombre;
  }

  buildScopePayload(role: string): ScopePayloadItem[] | null {
    if (role === 'admin') return [];
    if (role === 'user') {
      if (!this.cEntidadId) return null;
      return [{ entidadId: this.cEntidadId, areaId: this.cAreaId ?? undefined }];
    }
    if (role === 'soporte') {
      if (!this.cEntidadIds.length) return null;
      return this.cEntidadIds.map(id => ({ entidadId: id }));
    }
    return [];
  }

  buildEditScopePayload(role: string): ScopePayloadItem[] | null {
    if (role === 'admin') return [];
    if (role === 'user') {
      if (!this.eEntidadId) return null;
      return [{ entidadId: this.eEntidadId, areaId: this.eAreaId ?? undefined }];
    }
    if (role === 'soporte') {
      if (!this.eEntidadIds.length) return null;
      return this.eEntidadIds.map(id => ({ entidadId: id }));
    }
    return [];
  }

  // ── Crear: scope callbacks ─────────────────────────────────────────────────

  onCreateRoleChange(): void {
    this.cEntidadId = null;
    this.cAreaId = null;
    this.cEntidadIds = [];
    this.cAreasDisponibles = [];
  }

  onCreateEntidadChange(): void {
    this.cAreaId = null;
    this.cAreasDisponibles = [];
    if (!this.cEntidadId) return;
    this.cLoadingAreas = true;
    this.entidadesService.getAllAreas(this.cEntidadId).subscribe({
      next: (areas) => { this.cAreasDisponibles = areas; this.cLoadingAreas = false; },
      error: () => (this.cLoadingAreas = false),
    });
  }

  toggleCreateSoporte(id: number): void {
    const idx = this.cEntidadIds.indexOf(id);
    if (idx === -1) this.cEntidadIds.push(id);
    else this.cEntidadIds.splice(idx, 1);
  }

  isSoporteChecked(id: number): boolean {
    return this.cEntidadIds.includes(id);
  }

  // ── Editar: scope callbacks ────────────────────────────────────────────────

  onEditRoleChange(): void {
    this.eEntidadId = null;
    this.eAreaId = null;
    this.eEntidadIds = [];
    this.eAreasDisponibles = [];
  }

  onEditEntidadChange(): void {
    this.eAreaId = null;
    this.eAreasDisponibles = [];
    if (!this.eEntidadId) return;
    this.eLoadingAreas = true;
    this.entidadesService.getAllAreas(this.eEntidadId).subscribe({
      next: (areas) => { this.eAreasDisponibles = areas; this.eLoadingAreas = false; },
      error: () => (this.eLoadingAreas = false),
    });
  }

  toggleEditSoporte(id: number): void {
    const idx = this.eEntidadIds.indexOf(id);
    if (idx === -1) this.eEntidadIds.push(id);
    else this.eEntidadIds.splice(idx, 1);
  }

  isEditSoporteChecked(id: number): boolean {
    return this.eEntidadIds.includes(id);
  }

  // ── Modal Crear ────────────────────────────────────────────────────────────

  openCreate(): void {
    this.createForm.reset({ role: 'user', area: 'General' });
    this.cEntidadId = null;
    this.cAreaId = null;
    this.cEntidadIds = [];
    this.cAreasDisponibles = [];
    new bootstrap.Modal(document.getElementById('createModal')).show();
  }

  guardarUsuario(): void {
    if (this.createForm.invalid) { this.createForm.markAllAsTouched(); return; }

    const role = this.createForm.value.role;
    const scopePayload = this.buildScopePayload(role);

    if (scopePayload === null) {
      this.error = role === 'user'
        ? 'Debe seleccionar una entidad y un área para el usuario'
        : 'Debe seleccionar al menos una entidad para el soporte';
      return;
    }

    this.saving = true;
    this.usersService.create(this.createForm.value).subscribe({
      next: (newUser) => {
        if (scopePayload.length > 0) {
          this.usersService.setScope(newUser.id, scopePayload).subscribe({
            next: () => this.afterCreate(),
            error: () => {
              this.saving = false;
              bootstrap.Modal.getInstance(document.getElementById('createModal'))?.hide();
              this.loadUsers();
              this.showSuccess('Usuario creado (contraseña: usuario123). No se pudo asignar el scope — edite el usuario para asignarlo.');
            },
          });
        } else {
          this.afterCreate();
        }
      },
      error: (err) => {
        this.saving = false;
        this.error = err?.error?.message || 'Error al crear usuario';
      },
    });
  }

  private afterCreate(): void {
    this.saving = false;
    bootstrap.Modal.getInstance(document.getElementById('createModal'))?.hide();
    this.loadUsers();
    this.showSuccess('Usuario creado con contraseña predeterminada: usuario123');
  }

  // ── Modal Editar ───────────────────────────────────────────────────────────

  openEdit(user: User): void {
    this.editingUser = user;
    this.editForm.patchValue({
      nombre:   user.nombre,
      alias:    user.alias,
      role:     user.role,
      area:     user.area || 'General',
      telefono: user.telefono || '',
      activo:   user.activo,
    });

    // Pre-poblar scope
    this.eEntidadIds = [];
    this.eAreasDisponibles = [];
    this.eEntidadId = null;
    this.eAreaId = null;

    if (user.scope?.length) {
      if (user.role === 'soporte') {
        this.eEntidadIds = user.scope.map(s => s.entidadId);
      } else if (user.role === 'user') {
        this.eEntidadId = user.scope[0]?.entidadId ?? null;
        this.eAreaId = user.scope[0]?.areaId ?? null;
        if (this.eEntidadId) {
          this.eLoadingAreas = true;
          this.entidadesService.getAllAreas(this.eEntidadId).subscribe({
            next: (areas) => { this.eAreasDisponibles = areas; this.eLoadingAreas = false; },
            error: () => (this.eLoadingAreas = false),
          });
        }
      }
    }

    new bootstrap.Modal(document.getElementById('editModal')).show();
  }

  guardarEdicion(): void {
    if (this.editForm.invalid || !this.editingUser) { this.editForm.markAllAsTouched(); return; }

    const role = this.editForm.value.role;
    const scopePayload = this.buildEditScopePayload(role);

    this.savingEdit = true;
    this.usersService.update(this.editingUser.id, this.editForm.value).subscribe({
      next: () => {
        const userId = this.editingUser!.id;
        if (scopePayload !== null) {
          this.usersService.setScope(userId, scopePayload).subscribe({
            next: () => this.afterEdit(),
            error: () => {
              this.savingEdit = false;
              bootstrap.Modal.getInstance(document.getElementById('editModal'))?.hide();
              this.loadUsers();
              this.showSuccess('Usuario actualizado. No se pudo actualizar el scope.');
            },
          });
        } else {
          this.afterEdit();
        }
      },
      error: (err) => {
        this.savingEdit = false;
        this.error = err?.error?.message || 'Error al actualizar usuario';
      },
    });
  }

  private afterEdit(): void {
    this.savingEdit = false;
    bootstrap.Modal.getInstance(document.getElementById('editModal'))?.hide();
    this.loadUsers();
    this.showSuccess('Usuario actualizado');
  }

  // ── Otras acciones ─────────────────────────────────────────────────────────

  resetPassword(user: User): void {
    if (!confirm(`¿Restablecer la contraseña de "${user.nombre}" a "usuario123"?`)) return;
    this.usersService.resetPassword(user.id).subscribe({
      next: () => this.showSuccess(`Contraseña de ${user.nombre} restablecida`),
      error: (err) => (this.error = err?.error?.message || 'Error al restablecer'),
    });
  }

  eliminarUsuario(user: User): void {
    if (user.id === this.currentUser?.id) { this.error = 'No puede eliminar su propio usuario'; return; }
    if (!confirm(`¿Eliminar al usuario "${user.nombre}"?`)) return;
    this.usersService.delete(user.id).subscribe({
      next: () => { this.loadUsers(); this.showSuccess('Usuario eliminado'); },
      error: (err) => (this.error = err?.error?.message || 'Error al eliminar'),
    });
  }

  logout(): void { this.authService.logout(); }

  private showSuccess(msg: string): void {
    this.successMsg = msg;
    setTimeout(() => (this.successMsg = ''), 5000);
  }
}
<!-- Navbar -->
<nav class="navbar navbar-expand-lg navbar-dark" style="background: #1e40af;">
  <div class="container-fluid px-4">
    <span class="navbar-brand"><i class="bi bi-people me-2"></i>Gestión de Usuarios</span>
    <div class="d-flex align-items-center gap-2 ms-auto flex-wrap">
      <button class="btn btn-outline-light btn-sm" routerLink="/entidades">
        <i class="bi bi-building me-1"></i>Entidades
      </button>
      <button class="btn btn-outline-light btn-sm" routerLink="/areas">
        <i class="bi bi-diagram-3 me-1"></i>Áreas
      </button>
      <button class="btn btn-outline-light btn-sm" routerLink="/dashboard">
        <i class="bi bi-arrow-left me-1"></i>Dashboard
      </button>
      <button class="btn btn-outline-light btn-sm" (click)="logout()">
        <i class="bi bi-box-arrow-right me-1"></i>Salir
      </button>
    </div>
  </div>
</nav>

<div class="container-fluid px-4 py-4">
  <div class="alert alert-success alert-dismissible py-2" *ngIf="successMsg">
    <i class="bi bi-check-circle me-1"></i>{{ successMsg }}
    <button type="button" class="btn-close py-2" (click)="successMsg=''"></button>
  </div>
  <div class="alert alert-danger alert-dismissible py-2" *ngIf="error">
    <i class="bi bi-exclamation-circle me-1"></i>{{ error }}
    <button type="button" class="btn-close py-2" (click)="error=''"></button>
  </div>

  <div class="card">
    <div class="card-header d-flex justify-content-between align-items-center">
      <h5 class="mb-0 fw-bold" style="color:#1e40af;">
        <i class="bi bi-people-fill me-2"></i>Listado de Usuarios
      </h5>
      <button class="btn btn-primary btn-sm" (click)="openCreate()">
        <i class="bi bi-person-plus me-1"></i>Nuevo Usuario
      </button>
    </div>

    <div class="text-center py-5" *ngIf="loading">
      <div class="spinner-border text-primary" role="status"></div>
    </div>

    <div class="table-responsive" *ngIf="!loading">
      <table class="table table-hover mb-0">
        <thead>
          <tr>
            <th>#</th>
            <th>Nombre</th>
            <th>Alias</th>
            <th>Teléfono</th>
            <th>Rol</th>
            <th>Entidad / Área</th>
            <th>Estado</th>
            <th>Creación</th>
            <th class="text-center">Acciones</th>
          </tr>
        </thead>
        <tbody>
          <tr *ngFor="let u of users">
            <td class="text-muted fw-bold">{{ u.id }}</td>
            <td>{{ u.nombre }}</td>
            <td><code>{{ u.alias }}</code></td>
            <td class="small">
              <a *ngIf="u.telefono" [href]="'tel:'+u.telefono" class="text-decoration-none">
                <i class="bi bi-telephone me-1 text-success"></i>{{ u.telefono }}
              </a>
              <span *ngIf="!u.telefono" class="text-muted">—</span>
            </td>
            <td>
              <span class="badge bg-primary"            *ngIf="u.role==='admin'">Admin</span>
              <span class="badge bg-warning text-dark"  *ngIf="u.role==='soporte'">Soporte</span>
              <span class="badge bg-secondary"          *ngIf="u.role==='user'">Usuario</span>
            </td>
            <td class="small">
              <span *ngIf="u.role==='admin'" class="text-muted">—</span>
              <ng-container *ngIf="u.role!=='admin'">
                <!-- Scope asignado -->
                <ng-container *ngIf="u.scope?.length">
                  <!-- usuario: una entidad/area -->
                  <ng-container *ngIf="u.role==='user'">
                    <span class="badge bg-light text-dark border me-1">
                      <i class="bi bi-building me-1"></i>{{ u.scope![0].entidad?.nombre }}
                    </span>
                    <span *ngIf="u.scope![0].area" class="badge bg-light text-primary border">
                      <i class="bi bi-diagram-3 me-1"></i>{{ u.scope![0].area!.nombre }}
                    </span>
                  </ng-container>
                  <!-- soporte: múltiples entidades -->
                  <ng-container *ngIf="u.role==='soporte'">
                    <span class="badge bg-light text-dark border me-1"
                      *ngFor="let s of u.scope">
                      <i class="bi bi-building me-1"></i>{{ s.entidad?.nombre }}
                    </span>
                  </ng-container>
                </ng-container>
                <!-- Sin scope asignado: mostrar area legado -->
                <span *ngIf="!u.scope?.length" class="text-muted fst-italic small">
                  {{ u.area || 'Sin asignar' }}
                </span>
              </ng-container>
            </td>
            <td>
              <span class="badge bg-success"    *ngIf="u.activo">Activo</span>
              <span class="badge bg-secondary"  *ngIf="!u.activo">Inactivo</span>
            </td>
            <td class="small">{{ u.createdAt ? (u.createdAt | date:'dd/MM/yyyy') : '—' }}</td>
            <td class="text-center" style="white-space:nowrap">
              <button class="btn btn-outline-secondary btn-sm me-1" title="Editar" (click)="openEdit(u)">
                <i class="bi bi-pencil"></i>
              </button>
              <button class="btn btn-outline-warning btn-sm me-1" title="Restablecer Contraseña" (click)="resetPassword(u)">
                <i class="bi bi-arrow-repeat"></i>
              </button>
              <button class="btn btn-outline-danger btn-sm" title="Eliminar"
                (click)="eliminarUsuario(u)" [disabled]="u.id===currentUser?.id">
                <i class="bi bi-trash"></i>
              </button>
            </td>
          </tr>
          <tr *ngIf="users.length===0">
            <td colspan="9" class="text-center text-muted py-4">No hay usuarios registrados</td>
          </tr>
        </tbody>
      </table>
    </div>
  </div>
</div>

<!-- ══ MODAL: Crear Usuario ══════════════════════════════════════════════════ -->
<div class="modal fade" id="createModal" tabindex="-1">
  <div class="modal-dialog modal-lg">
    <div class="modal-content">
      <div class="modal-header">
        <h5 class="modal-title"><i class="bi bi-person-plus me-2"></i>Nuevo Usuario</h5>
        <button type="button" class="btn-close" data-bs-dismiss="modal"></button>
      </div>
      <div class="modal-body">
        <div class="alert alert-info py-2 small mb-3">
          <i class="bi bi-info-circle me-1"></i>Contraseña predeterminada: <strong>usuario123</strong>
        </div>

        <form [formGroup]="createForm">
          <div class="row g-3">
            <div class="col-12">
              <label class="form-label fw-semibold">Nombre completo <span class="text-danger">*</span></label>
              <input type="text" class="form-control" formControlName="nombre" placeholder="Nombre del usuario" />
              <div class="text-danger small mt-1"
                *ngIf="createForm.get('nombre')?.touched && createForm.get('nombre')?.invalid">Mínimo 3 caracteres</div>
            </div>
            <div class="col-md-6">
              <label class="form-label fw-semibold">Alias <span class="text-danger">*</span></label>
              <input type="text" class="form-control" formControlName="alias" placeholder="Alias de acceso" />
              <div class="text-danger small mt-1"
                *ngIf="createForm.get('alias')?.touched && createForm.get('alias')?.invalid">Mínimo 3 caracteres</div>
            </div>
            <div class="col-md-6">
              <label class="form-label fw-semibold">Teléfono</label>
              <input type="tel" class="form-control" formControlName="telefono" placeholder="Ej: 3001234567" />
            </div>
            <div class="col-md-6">
              <label class="form-label fw-semibold">Rol <span class="text-danger">*</span></label>
              <select class="form-select" formControlName="role" (change)="onCreateRoleChange()">
                <option value="user">Usuario</option>
                <option value="soporte">Soporte</option>
                <option value="admin">Administrador</option>
              </select>
            </div>
            <div class="col-md-6">
              <label class="form-label fw-semibold">Área (sistema legado)</label>
              <select class="form-select" formControlName="area">
                <option *ngFor="let a of areas" [value]="a">{{ a }}</option>
              </select>
            </div>
          </div>
        </form>

        <!-- ── Sección de scope ── -->
        <hr class="my-3">

        <!-- Rol: user → una entidad + un área -->
        <ng-container *ngIf="createForm.get('role')?.value === 'user'">
          <p class="fw-semibold mb-2 text-primary"><i class="bi bi-building me-1"></i>Asignación de entidad y área</p>
          <div class="row g-3">
            <div class="col-md-6">
              <label class="form-label fw-semibold">Entidad <span class="text-danger">*</span></label>
              <select class="form-select" [(ngModel)]="cEntidadId" [ngModelOptions]="{standalone:true}"
                (change)="onCreateEntidadChange()">
                <option [ngValue]="null">-- Seleccione entidad --</option>
                <option *ngFor="let e of entidades" [ngValue]="e.id">{{ e.nombre }}</option>
              </select>
            </div>
            <div class="col-md-6">
              <label class="form-label fw-semibold">Área <span class="text-danger">*</span></label>
              <select class="form-select" [(ngModel)]="cAreaId" [ngModelOptions]="{standalone:true}"
                [disabled]="!cEntidadId || cLoadingAreas">
                <option [ngValue]="null">{{ cLoadingAreas ? 'Cargando...' : '-- Seleccione área --' }}</option>
                <option *ngFor="let a of cAreasDisponibles" [ngValue]="a.id">{{ a.nombre }}</option>
              </select>
              <div class="form-text text-muted" *ngIf="!cEntidadId">Primero seleccione una entidad</div>
              <div class="form-text text-warning" *ngIf="cEntidadId && !cAreasDisponibles.length && !cLoadingAreas">
                Esta entidad no tiene áreas registradas. <a routerLink="/areas">Crear áreas</a>
              </div>
            </div>
          </div>
        </ng-container>

        <!-- Rol: soporte → múltiples entidades -->
        <ng-container *ngIf="createForm.get('role')?.value === 'soporte'">
          <p class="fw-semibold mb-2 text-warning"><i class="bi bi-building me-1"></i>Entidades que puede atender <span class="text-danger">*</span></p>
          <div class="border rounded p-2" style="max-height:180px;overflow-y:auto">
            <div class="form-check" *ngFor="let e of entidades">
              <input class="form-check-input" type="checkbox"
                [id]="'ce-'+e.id"
                [checked]="isSoporteChecked(e.id)"
                (change)="toggleCreateSoporte(e.id)" />
              <label class="form-check-label" [for]="'ce-'+e.id">{{ e.nombre }}</label>
            </div>
            <div class="text-muted small fst-italic p-1" *ngIf="!entidades.length">
              No hay entidades registradas. <a routerLink="/entidades">Crear entidades</a>
            </div>
          </div>
          <div class="form-text">Seleccionadas: <strong>{{ cEntidadIds.length }}</strong></div>
        </ng-container>

        <!-- Rol: admin → sin scope -->
        <ng-container *ngIf="createForm.get('role')?.value === 'admin'">
          <p class="text-muted small fst-italic"><i class="bi bi-shield-check me-1"></i>Los administradores tienen acceso global, no requieren asignación de entidad.</p>
        </ng-container>
      </div>
      <div class="modal-footer">
        <button type="button" class="btn btn-secondary" data-bs-dismiss="modal">Cancelar</button>
        <button type="button" class="btn btn-primary" (click)="guardarUsuario()" [disabled]="saving">
          <span *ngIf="saving" class="spinner-border spinner-border-sm me-1"></span>
          {{ saving ? 'Guardando...' : 'Crear Usuario' }}
        </button>
      </div>
    </div>
  </div>
</div>

<!-- ══ MODAL: Editar Usuario ═════════════════════════════════════════════════ -->
<div class="modal fade" id="editModal" tabindex="-1">
  <div class="modal-dialog modal-lg">
    <div class="modal-content">
      <div class="modal-header">
        <h5 class="modal-title"><i class="bi bi-pencil me-2"></i>Editar Usuario</h5>
        <button type="button" class="btn-close" data-bs-dismiss="modal"></button>
      </div>
      <div class="modal-body">
        <form [formGroup]="editForm">
          <div class="row g-3">
            <div class="col-12">
              <label class="form-label fw-semibold">Nombre completo <span class="text-danger">*</span></label>
              <input type="text" class="form-control" formControlName="nombre" />
              <div class="text-danger small mt-1"
                *ngIf="editForm.get('nombre')?.touched && editForm.get('nombre')?.invalid">Mínimo 3 caracteres</div>
            </div>
            <div class="col-md-6">
              <label class="form-label fw-semibold">Alias <span class="text-danger">*</span></label>
              <input type="text" class="form-control" formControlName="alias" />
              <div class="text-danger small mt-1"
                *ngIf="editForm.get('alias')?.touched && editForm.get('alias')?.invalid">Mínimo 3 caracteres</div>
            </div>
            <div class="col-md-6">
              <label class="form-label fw-semibold">Teléfono</label>
              <input type="tel" class="form-control" formControlName="telefono" />
            </div>
            <div class="col-md-6">
              <label class="form-label fw-semibold">Rol</label>
              <select class="form-select" formControlName="role" (change)="onEditRoleChange()">
                <option value="user">Usuario</option>
                <option value="soporte">Soporte</option>
                <option value="admin">Administrador</option>
              </select>
            </div>
            <div class="col-md-6">
              <label class="form-label fw-semibold">Área (sistema legado)</label>
              <select class="form-select" formControlName="area">
                <option *ngFor="let a of areas" [value]="a">{{ a }}</option>
              </select>
            </div>
            <div class="col-12">
              <div class="form-check">
                <input class="form-check-input" type="checkbox" formControlName="activo" id="activoCheck" />
                <label class="form-check-label" for="activoCheck">Usuario activo</label>
              </div>
            </div>
          </div>
        </form>

        <!-- ── Sección scope editar ── -->
        <hr class="my-3">

        <!-- Rol: user -->
        <ng-container *ngIf="editForm.get('role')?.value === 'user'">
          <p class="fw-semibold mb-2 text-primary"><i class="bi bi-building me-1"></i>Asignación de entidad y área</p>
          <div class="row g-3">
            <div class="col-md-6">
              <label class="form-label fw-semibold">Entidad</label>
              <select class="form-select" [(ngModel)]="eEntidadId" [ngModelOptions]="{standalone:true}"
                (change)="onEditEntidadChange()">
                <option [ngValue]="null">-- Seleccione entidad --</option>
                <option *ngFor="let e of entidades" [ngValue]="e.id">{{ e.nombre }}</option>
              </select>
            </div>
            <div class="col-md-6">
              <label class="form-label fw-semibold">Área</label>
              <select class="form-select" [(ngModel)]="eAreaId" [ngModelOptions]="{standalone:true}"
                [disabled]="!eEntidadId || eLoadingAreas">
                <option [ngValue]="null">{{ eLoadingAreas ? 'Cargando...' : '-- Seleccione área --' }}</option>
                <option *ngFor="let a of eAreasDisponibles" [ngValue]="a.id">{{ a.nombre }}</option>
              </select>
            </div>
          </div>
        </ng-container>

        <!-- Rol: soporte -->
        <ng-container *ngIf="editForm.get('role')?.value === 'soporte'">
          <p class="fw-semibold mb-2 text-warning"><i class="bi bi-building me-1"></i>Entidades que puede atender</p>
          <div class="border rounded p-2" style="max-height:180px;overflow-y:auto">
            <div class="form-check" *ngFor="let e of entidades">
              <input class="form-check-input" type="checkbox"
                [id]="'ee-'+e.id"
                [checked]="isEditSoporteChecked(e.id)"
                (change)="toggleEditSoporte(e.id)" />
              <label class="form-check-label" [for]="'ee-'+e.id">{{ e.nombre }}</label>
            </div>
          </div>
          <div class="form-text">Seleccionadas: <strong>{{ eEntidadIds.length }}</strong></div>
        </ng-container>

        <!-- Rol: admin -->
        <ng-container *ngIf="editForm.get('role')?.value === 'admin'">
          <p class="text-muted small fst-italic"><i class="bi bi-shield-check me-1"></i>Los administradores tienen acceso global.</p>
        </ng-container>
      </div>
      <div class="modal-footer">
        <button type="button" class="btn btn-secondary" data-bs-dismiss="modal">Cancelar</button>
        <button type="button" class="btn btn-primary" (click)="guardarEdicion()" [disabled]="savingEdit">
          <span *ngIf="savingEdit" class="spinner-border spinner-border-sm me-1"></span>
          {{ savingEdit ? 'Guardando...' : 'Guardar Cambios' }}
        </button>
      </div>
    </div>
  </div>
</div>
